package com.nimbusbill.customer.controller; import com.nimbusbill.customer.dto.*; import com.nimbusbill.customer.service.AiAssistantService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/ai") public class AiAssistantController{private final AiAssistantService service;public AiAssistantController(AiAssistantService s){service=s;}@PostMapping("/ask") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','OPERATIONS','AUDITOR','READ_ONLY','AI_ANALYST')") public AiAssistantResponse ask(@Valid @RequestBody AiAssistantRequest r,Authentication a){return service.ask(r,a);}}
